  // Show encounter panel repurposed for branch choice
  const enc = {
    icon: '⛏', title: 'VEIN CRACKED — CHOOSE A SEAM',
    desc,
    options: [
      { label: `← Left seam`, cls: 'safe',
        action: () => resolveBranch(leftIsReal) },
      { label: `Right seam →`, cls: '',
        action: () => resolveBranch(!leftIsReal) },
    ]
  };
  showEncounterPanel(enc);
}
