function _handleBLMineNPCInteraction() {
  if (!gameState.inBLMine) return false;
  const fl = gameState.blMineFloor;
  if (blMineNPCTalkOpen) { closeBLMineNPCTalk(); return true; }
  for (const npc of BL_MINE_NPCS) {
