function drawBLMineNPCs(cx, cy) {
  const fl = gameState.blMineFloor;
  for (const npc of BL_MINE_NPCS) {
    if (npc.floor !== fl) continue;
    if (!isBLMineExplored(fl, npc.tx, npc.ty)) continue;
