function rebuildPenTiles(pen) {
  const { x:tx, y:ty, w, h } = pen;
  for (let dx = 0; dx < w; dx++) {
    setT(tx+dx, ty,   TL.FENCE);
    setT(tx+dx, ty+h-1, TL.FENCE);
  }
  for (let dy = 1; dy < h-1; dy++) {
    setT(tx,     ty+dy, TL.FENCE);
    setT(tx+w-1, ty+dy, TL.FENCE);
