      else { ctx.fillStyle='#2c2010'; ctx.fillRect(sx+5,sy+OC_T/2+1,1,OC_T/2-3); ctx.fillRect(sx+OC_T-6,sy+2,1,OC_T/2-1); }
      if(seed%3===0){ ctx.fillStyle='rgba(200,180,140,.1)'; ctx.fillRect(sx+2,sy+2,OC_T-4,3); }
