      ctx.lineTo(sx+OC_T/2-4,sy+9);
      ctx.lineTo(sx+OC_T/2+4,sy+9);
      ctx.lineTo(sx+OC_T/2+4,sy+11);
      ctx.lineTo(sx+OC_T/2-4,sy+11);
      ctx.lineTo(sx+OC_T/2-4,sy+13);
      ctx.closePath(); ctx.fill();
