    // Top surface — flat reddish plateau
    ctx.fillStyle='#b84828'; ctx.fillRect(sx,sy,T,T);
    ctx.fillStyle='#c85838'; ctx.fillRect(sx,sy,T,T/2);
    // Strata bands
    ctx.fillStyle='#d06840'; ctx.fillRect(sx,sy+3,T,4);
    ctx.fillStyle='#a03820'; ctx.fillRect(sx,sy+T/2-2,T,3);
    ctx.fillStyle='#c04030'; ctx.fillRect(sx,sy+T-8,T,5);
