    if(!mS){ ctx.fillStyle='rgba(0,0,0,.45)'; ctx.fillRect(sx,sy+T-6,T,6); ctx.fillStyle='#6a1a08'; ctx.fillRect(sx,sy+T-7,T,2); }
    if(!mE){ ctx.fillStyle='rgba(0,0,0,.35)'; ctx.fillRect(sx+T-5,sy,5,T); ctx.fillStyle='#6a1a08'; ctx.fillRect(sx+T-6,sy,2,T); }
    if(!mW){ ctx.fillStyle='rgba(255,180,100,.12)'; ctx.fillRect(sx,sy,3,T); }
    if(!mN){ ctx.fillStyle='rgba(255,200,120,.15)'; ctx.fillRect(sx,sy,T,3); }
    // Surface pitting
    ctx.fillStyle='rgba(80,20,5,.25)'; ctx.fillRect(sx+(h%10)+4,sy+(h2%8)+6,3,2);
    // Flat top highlight (interior tiles only)
    if(mN&&mS&&mW&&mE){ ctx.fillStyle='rgba(220,140,80,.12)'; ctx.fillRect(sx,sy,T,T); }

  } else if(t===BL.CANYON) {
    const cN=getBLT(tx,ty-1)===BL.CANYON, cS=getBLT(tx,ty+1)===BL.CANYON;
    const cW=getBLT(tx-1,ty)===BL.CANYON, cE=getBLT(tx+1,ty)===BL.CANYON;
