    const bT=t+bar*BAR, root=roots[bar], chord=chords[bar];
    // Waltz BOOM on beat 1
    wBass(root, bT, 0.75, V*0.92);
    // Bass fill — walk up on beat 3 of bars 3, 7, 11 (approaching chord change)
    if(bar%4===2) {
