function _handleJGInteraction() {
  if (!gameState.inJungle) return false;

  // Panel close takes highest priority
  if (_tobiasPanelOpen) { closeTobiasPanel(); return true; }
  if (jgTalkOpen)       { closeJGTalk();      return true; }

