      if (doc.goldValue > 0) {
        player.gold += doc.goldValue;
        spawnParticles(player.x, player.y, '#f0d060', 4, '+$' + doc.goldValue);
      }
    }, doc.text.length * 3600 + 200);
    break; // one doc per frame
