        break;
      case 'holy_axe':
        ctx.fillStyle = PAL.PALE_GOLD;
        ctx.fillRect(-2,-5, 4, 8);
        ctx.fillStyle = PAL.GOLD;
        ctx.fillRect(-5,-5, 3, 6);
        ctx.fillStyle = PAL.WHITE;
        ctx.fillRect(-5,-5, 2, 2);
