      ctx.fillRect(sx, sy, 6, 2);    /* blade */
      ctx.fillStyle = PAL.STONE_HIGH;
      ctx.fillRect(sx + 6, sy - 1, 2, 4);  /* handle guard */
      ctx.fillStyle = PAL.WHITE;
      ctx.fillRect(sx, sy, 1, 1);    /* tip glint */
