  ctx.fillStyle = zpal.solidShad;
  [6, 15, 26, 38, 50].forEach(col => {
    const fx = col * T, fy = 9 * T;
    ctx.fillRect(fx + 2, fy + 4, 8, 1);
    ctx.fillRect(fx + 6, fy + 2, 1, 5);
