    const g = playNote({
      wave:  waveP125,
      freq:  pitch(step.p1.semi),
      start: time,
      dur:   stepDur,
      vol:   step.p1.vol,
      vibrato: step.p1.vib,
    });
    pulse1MusicGain = g;
  }

  /* pulse2 — 25% duty, structural harmony */
  if (step.p2) {
    playNote({
      wave:  waveP25,
      freq:  pitch(step.p2.semi),
      start: time,
      dur:   stepDur,
      vol:   step.p2.vol,
      vibrato: step.p2.vib,
    });
  }

  /* triangle — bass line, one octave lower */
  if (step.tri) {
    playNote({
      wave:  waveTri,
      freq:  pitch(step.tri.semi),
      start: time,
      dur:   stepDur * 0.95,
      vol:   step.tri.vol,
    });
  }

  /* noise — percussion/atmosphere layer */
  if (step.noise) {
    playNoise({
      start: time,
      dur:   stepDur * 0.5,
      vol:   step.noise.vol,
      short: step.noise.short,
    });
  }
}
