  if(t===T.WALL)    return false;
  if(t===T.CHASM)   return !!G.chasmed[k];
  if(t===T.BIODOOR) return !!G.doored[k];
  // BIO_GEN, CORPSE_PIT, SPORE_VENT are all passable floor tiles
