function updateParticles(dt){
  for(let i=G.particles.length-1;i>=0;i--){
    const p=G.particles[i];
    p.vy += 220*dt;            // gravity
    p.vx *= Math.pow(0.82,60*dt);
    p.vy *= Math.pow(0.86,60*dt);
    p.x  += p.vx*dt;
    p.y  += p.vy*dt;
