    localStorage.setItem('re_runs',       prev.runs+1);
    const b=document.getElementById('wbest');
    b.innerHTML=`LIFETIME — ${prev.runs+1} runs | ${prev.lifeOrgans+G.graftsEquipped} organs | ${prev.lifeTiles+G.tilesTransformed} tiles`;
  } catch(e){}
}
